'use strict';

/**
 * Error thrown for any failed DigitalPaye API request.
 *
 * @property {string} code    Machine-readable error key (e.g. "Unauthorized", "NotFound")
 * @property {number} status  HTTP status code
 * @property {*}      details Additional error details returned by the API, if any
 */
class DigitalPayeError extends Error {
  constructor(code, message, status, details) {
    super(message);
    this.name = 'DigitalPayeError';
    this.code = code;
    this.status = status;
    this.details = details || null;
    if (Error.captureStackTrace) {
      Error.captureStackTrace(this, DigitalPayeError);
    }
  }
}

module.exports = { DigitalPayeError };
